import{_ as e,o as a,c as o,a3 as r}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Tenant Application — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant Application — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/tenant-application"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant Application — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/tenant-application"}]]},"headers":[],"relativePath":"user-guide/tenant-application.md","filePath":"user-guide/tenant-application.md","lastUpdated":1787319539000}'),n={name:"user-guide/tenant-application.md"};function s(d,t,i,l,c,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="tenant-application-—-user-guide" tabindex="-1">Tenant Application — User Guide <a class="header-anchor" href="#tenant-application-—-user-guide" aria-label="Permalink to &quot;Tenant Application — User Guide&quot;">​</a></h1><p>The Tenant Application is your workspace home. It uses the same layout as the Central admin console so navigation, headers, and page structure feel familiar.</p><h2 id="tenant-navigation" tabindex="-1">Tenant navigation <a class="header-anchor" href="#tenant-navigation" aria-label="Permalink to &quot;Tenant navigation&quot;">​</a></h2><p>The left sidebar includes:</p><table tabindex="0"><thead><tr><th>Item</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Dashboard</strong></td><td>Workspace overview with module widgets</td></tr><tr><td><strong>Leads</strong></td><td>CRM pipeline (Kanban/table, notes, follow-ups)</td></tr><tr><td><strong>Tasks</strong></td><td>Work items (board/list, status, priority, comments)</td></tr><tr><td><strong>Templates</strong></td><td>Communication Templates (plain-text messages, WhatsApp from Leads)</td></tr><tr><td><strong>Settings</strong></td><td>Workspace preferences</td></tr><tr><td><strong>Profile</strong></td><td>Your name, email, password, and optional profile photo</td></tr></tbody></table><p>Header actions match Central:</p><ul><li>Collapse / expand the sidebar (<code>⌘B</code> / <code>Ctrl+B</code>)</li><li>Breadcrumbs</li><li>Search pages (<code>⌘K</code> / <code>Ctrl+K</code>) — jumps between sidebar pages</li><li>Theme toggle</li><li><strong>Notifications</strong> — realtime in-app list and unread badge, with polling fallback when the live connection is unavailable</li><li>Settings shortcut</li><li>Account menu (Profile, Settings, Log out)</li></ul><h3 id="keyboard-shortcuts-modules" tabindex="-1">Keyboard shortcuts (modules) <a class="header-anchor" href="#keyboard-shortcuts-modules" aria-label="Permalink to &quot;Keyboard shortcuts (modules)&quot;">​</a></h3><p>On a module list page (for example Leads or Tasks):</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>N</code></td><td>Open <strong>New</strong> (same as the New button; requires create permission). Not <code>Ctrl+N</code> — browsers reserve that for a new window.</td></tr><tr><td><code>⌘F</code> / <code>Ctrl+F</code></td><td>Focus that module’s search box (filters the current list, not the whole workspace)</td></tr><tr><td><code>⌘B</code> / <code>Ctrl+B</code></td><td>Toggle the sidebar</td></tr><tr><td><code>⌘K</code> / <code>Ctrl+K</code></td><td>Search and jump to another page</td></tr></tbody></table><p>Shortcuts do not fire while you are typing in a form field.</p><p>Only modules available to every workspace are listed today. Additional purchased modules will appear in the sidebar when they are installed.</p><h2 id="marketplace-add-remove-modules" tabindex="-1">Marketplace (add / remove modules) <a class="header-anchor" href="#marketplace-add-remove-modules" aria-label="Permalink to &quot;Marketplace (add / remove modules)&quot;">​</a></h2><p>Open <strong>Settings → Marketplace → Open Marketplace</strong>, or go to <code>/#/marketplace</code> when Marketplace is enabled.</p><table tabindex="0"><thead><tr><th>Action</th><th>Who</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Install</strong> / <strong>Subscribe</strong></td><td><code>marketplace.purchase</code></td><td>Free modules activate immediately; paid modules go through checkout</td></tr><tr><td><strong>Remove</strong> / <strong>Cancel subscription</strong></td><td><code>marketplace.purchase</code></td><td>Opt-in modules only — not core Leads/Tasks. Remove <strong>dependents</strong> first when prompted (modules that need this one)</td></tr><tr><td><strong>Browse</strong></td><td><code>marketplace.view</code></td><td>Catalog search, filter chips (<strong>Installed</strong> / <strong>Available</strong> / <strong>Paid</strong> / <strong>Free</strong>), and module details. Badges: <strong>Installed</strong>, <strong>Available</strong> (free), <strong>Billable</strong> (paid), or <strong>Pending</strong></td></tr></tbody></table><p>When a module requires another module that is not installed yet, the detail drawer lists the dependency with its fee (<strong>Free</strong> or subscription price) and an <strong>Install</strong> / <strong>Subscribe</strong> action. Enable required modules first; the parent module’s Install/Subscribe unlocks afterward.</p><h3 id="catalog-pricing-current" tabindex="-1">Catalog pricing (current) <a class="header-anchor" href="#catalog-pricing-current" aria-label="Permalink to &quot;Catalog pricing (current)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Modules</th><th>Price</th></tr></thead><tbody><tr><td><strong>Included free</strong></td><td>Leads, Tasks</td><td>Auto-installed on every workspace</td></tr><tr><td><strong>Free to install</strong></td><td>Contacts, Companies, Calendar, Meetings, Activities, Opportunities, Quotations, Contracts, Communication Templates</td><td>$0 — install from Marketplace</td></tr><tr><td><strong>Paid</strong></td><td>Branded</td><td><strong>$29/month</strong> or <strong>$290/year</strong> (USD catalog)</td></tr></tbody></table><p>Marketplace shows paid prices in your <strong>workspace currency</strong> (Settings → General) as an approximate conversion from the USD catalog. <strong>Checkout is still billed in the catalog currency (USD)</strong> via the payment provider. Commercial flags live on the Central <code>modules</code> catalog. Full table: <a href="/developer-guide/entitlements">Entitlements</a>.</p><h2 id="dashboard-overview" tabindex="-1">Dashboard overview <a class="header-anchor" href="#dashboard-overview" aria-label="Permalink to &quot;Dashboard overview&quot;">​</a></h2><p><code>GET /dashboard</code> returns workspace info plus a <strong>widget registry</strong>. You may see:</p><ul><li><strong>Pipeline / sources / revenue</strong> — when Leads is installed and you can view leads. The <strong>Pipeline Board</strong> widget tints each stage column and its cards from that stage’s color (falls back to a default palette when a color is missing).</li><li><strong>High Priority</strong> — open leads with priority <strong>High</strong> only (<strong>not</strong> Urgent; intentional). Mark/clear from the lead drawer; clear restores the prior priority when known.</li><li><strong>Today’s / overdue follow-ups</strong> and deals closing soon — Leads-scoped</li><li><strong>Upcoming / overdue tasks</strong> — when Tasks is installed and you can view tasks</li><li><strong>Upcoming events</strong> — when Calendar is installed and you can view calendar</li><li><strong>Activity feed</strong>, <strong>notifications</strong> preview, and <strong>quick actions</strong></li></ul><p>Widget data respects module licensing, your permissions, and assignee scope (without assign permission you only see your own leads/tasks; Calendar uses <code>calendar.view_all</code> for org vs mine).</p><h2 id="switching-apps" tabindex="-1">Switching apps <a class="header-anchor" href="#switching-apps" aria-label="Permalink to &quot;Switching apps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>App</th><th>Typical entry</th></tr></thead><tbody><tr><td>Tenant (workspace)</td><td><code>/login</code> → <code>/dashboard</code></td></tr><tr><td>Central (platform admin)</td><td><code>/central/login</code> → <code>/central/dashboard</code></td></tr></tbody></table><p>Sessions are isolated. Logging into one app does not automatically sign you into the other.</p>',26)])])}const u=e(n,[["render",s]]);export{h as __pageData,u as default};
